/* @lc app=leetcode id=3272 lang=kotlin */ class Solution { fun f(x: Int): Long = (1..x).fold(1L) { a, b -> a * b } fun countGoodIntegers(n: Int, k: Int): Long = ((n + 1) / 2).let { h -> Math.pow(10.0, (h - 1).toDouble()).toInt().let { lo -> (lo until lo * 10).map { b -> b.toString().let { s -> s + s.dropLast(n % 2).reversed() } }.filter { it.toLong() % k == 0L }.map { String(it.toCharArray().sortedArray()) }.toSet().map { s -> s.groupingBy { it }.eachCount().let { c -> c.values.fold(1L) { a, v -> a * f(v) }.let { den -> f(n) / den - (c['0']?.let { z -> f(n - 1) / (den / z) } ?: 0L) } } }.sum() } } }